using FaceFusion.Face;
using FaceFusion.Types;
using OpenCvSharp;

namespace FaceFusion.UnitTests;

/// <summary>
/// Port of the ground-truth checks for <c>facefusion/face_helper.py</c>. There is no
/// <c>tests/test_face_helper.py</c> in the Python suite, so all expected values below were
/// generated by running the actual Python implementation.
///
/// <para>
/// <b>Ground-truth provenance — read this before trusting a number below.</b>
/// </para>
/// <para>
/// <b>Real numpy-verified ground truth</b> (transcribed <c>facefusion/face_helper.py</c> run
/// under real Python 3 + numpy 2.4.6, no cv2 involved): <c>CreateStaticAnchors</c>,
/// <c>DistanceToBoundingBox</c>, <c>DistanceToFaceLandmark5</c>, <c>ScaleFaceLandmark5</c>,
/// <c>ConvertToFaceLandmark5</c>, <c>EstimateFaceAngle</c>, <c>GetNmsThreshold</c>,
/// <c>CreateBoundingBox</c>, <c>NormalizeBoundingBox</c>, <c>CalculateBoundingBoxOverlap</c>,
/// <c>AveragePoints</c>.
/// </para>
/// <para>
/// <b>Real cv2-verified ground truth</b> (the environment was upgraded mid-task to
/// opencv-python-headless 5.0.0; the same transcribed Python module was run for real, calling
/// actual <c>cv2.estimateAffinePartial2D</c> / <c>cv2.warpAffine</c> / <c>cv2.getAffineTransform</c>
/// / <c>cv2.invertAffineTransform</c> / <c>cv2.transform</c> / <c>cv2.getRotationMatrix2D</c> /
/// <c>cv2.dnn.NMSBoxes</c>): <c>EstimateMatrixByFaceLandmark5</c>, <c>WarpFaceByFaceLandmark5</c>,
/// <c>WarpFaceByBoundingBox</c>, <c>WarpFaceByTranslation</c>, <c>CalculatePasteArea</c> (including
/// the int32-rounding quirk documented on <see cref="FaceHelper.CalculatePasteArea"/>),
/// <c>PasteBack</c>, <c>CreateRotationMatrixAndSize</c>, <c>MergeMatrix</c>, <c>ApplyNms</c>. These
/// compare against a tolerance (matrix values: 1e-4 absolute; warped-pixel sums: within 2000
/// out of a several-million total, via <see cref="AssertPixelSumClose"/>; corner pixels that
/// land exactly on an un-interpolated source pixel: exact) rather than bit-for-bit, because the
/// C# side runs against OpenCvSharp4 4.13's native OpenCV build while the ground truth ran
/// against opencv-python-headless 5.0.0's — two different builds of the same algorithm that
/// resolve INTER_AREA/INTER_LINEAR sub-pixel sampling with tiny rounding differences at some
/// pixels, but close enough that a wrong flag, transposed matrix, or dtype-promotion bug would
/// fail the tolerance immediately (which is the point of these tests).
/// </para>
/// <para>
/// <b>Property-only (no Python ground truth)</b>: none — every function in scope got either
/// numpy or cv2 ground truth once cv2 became available in this environment. A few tests below
/// additionally check structural properties (invertibility, warp-then-unwarp round trip) as a
/// second, independent line of defense on top of the ground-truth comparison, not as a
/// substitute for it.
/// </para>
/// </summary>
public sealed class FaceHelperTests
{
    private const double MatrixTolerance = 1e-4;

    // -----------------------------------------------------------------
    // WARP_TEMPLATE_SET
    // -----------------------------------------------------------------

    [Fact]
    public void GetWarpTemplate_Arcface112V1_MatchesPythonLiteralsExactly()
    {
        var template = FaceHelper.GetWarpTemplate(WarpTemplate.Arcface112V1);

        Assert.Equal(0.35473214, template[0, 0], 8);
        Assert.Equal(0.45658929, template[0, 1], 8);
        Assert.Equal(0.64526786, template[1, 0], 8);
        Assert.Equal(0.45658929, template[1, 1], 8);
        Assert.Equal(0.50000000, template[2, 0], 8);
        Assert.Equal(0.61154464, template[2, 1], 8);
        Assert.Equal(0.37913393, template[3, 0], 8);
        Assert.Equal(0.77687500, template[3, 1], 8);
        Assert.Equal(0.62086607, template[4, 0], 8);
        Assert.Equal(0.77687500, template[4, 1], 8);
    }

    [Fact]
    public void GetWarpTemplate_Ffhq512_MatchesPythonLiteralsExactly()
    {
        var template = FaceHelper.GetWarpTemplate(WarpTemplate.Ffhq512);

        Assert.Equal(0.37691676, template[0, 0], 8);
        Assert.Equal(0.46864664, template[0, 1], 8);
        Assert.Equal(0.61150205, template[4, 0], 8);
        Assert.Equal(0.72490465, template[4, 1], 8);
    }

    [Fact]
    public void GetWarpTemplate_ReturnsDefensiveCopy()
    {
        var first = FaceHelper.GetWarpTemplate(WarpTemplate.Arcface128);
        first[0, 0] = -999;
        var second = FaceHelper.GetWarpTemplate(WarpTemplate.Arcface128);

        Assert.Equal(0.36167656, second[0, 0], 8);
    }

