    [Fact]
    public void CreateStaticAnchors_Stride8Total2_MatchesNumpy()
    {
        var anchors = FaceHelper.CreateStaticAnchors(8, 2, 3, 4);

        Assert.Equal(24, anchors.GetLength(0));

        float[,] expected =
        {
            { 0, 0 }, { 0, 0 }, { 8, 0 }, { 8, 0 }, { 16, 0 }, { 16, 0 },
            { 0, 8 }, { 0, 8 }, { 8, 8 }, { 8, 8 }, { 16, 8 }, { 16, 8 },
            { 0, 16 }, { 0, 16 }, { 8, 16 }, { 8, 16 }, { 16, 16 }, { 16, 16 },
            { 0, 24 }, { 0, 24 }, { 8, 24 }, { 8, 24 }, { 16, 24 }, { 16, 24 },
        };

        for (var i = 0; i < 24; i++)
        {
            Assert.Equal(expected[i, 0], anchors[i, 0]);
            Assert.Equal(expected[i, 1], anchors[i, 1]);
        }
    }

    [Fact]
    public void CreateStaticAnchors_Stride16Total3_MatchesNumpy()
    {
        var anchors = FaceHelper.CreateStaticAnchors(16, 3, 2, 2);

        float[,] expected =
        {
            { 0, 0 }, { 0, 0 }, { 0, 0 },
            { 16, 0 }, { 16, 0 }, { 16, 0 },
            { 0, 16 }, { 0, 16 }, { 0, 16 },
            { 16, 16 }, { 16, 16 }, { 16, 16 },
        };

        Assert.Equal(12, anchors.GetLength(0));
        for (var i = 0; i < 12; i++)
        {
            Assert.Equal(expected[i, 0], anchors[i, 0]);
            Assert.Equal(expected[i, 1], anchors[i, 1]);
        }
    }

    [Fact]
    public void CreateStaticAnchors_CachedCall_ReturnsIndependentCopy()
    {
        var first = FaceHelper.CreateStaticAnchors(8, 2, 3, 4);
        first[0, 0] = -1;
        var second = FaceHelper.CreateStaticAnchors(8, 2, 3, 4);

        Assert.Equal(0, second[0, 0]);
    }

