    [Fact]
    public void DistanceToBoundingBox_MatchesNumpy()
    {
        var points = new float[,] { { 10f, 20f }, { 30f, 40f } };
        var distance = new float[,] { { 1f, 2f, 3f, 4f }, { 5f, 6f, 7f, 8f } };

        var result = FaceHelper.DistanceToBoundingBox(points, distance);

        Assert.Equal(new[] { 9f, 18f, 13f, 24f }, new[] { result[0, 0], result[0, 1], result[0, 2], result[0, 3] });
        Assert.Equal(new[] { 25f, 34f, 37f, 48f }, new[] { result[1, 0], result[1, 1], result[1, 2], result[1, 3] });
    }

    [Fact]
    public void DistanceToFaceLandmark5_MatchesNumpy()
    {
        var points = new float[,] { { 100f, 200f } };
        var distance = new float[,] { { 1f, 2f, 3f, 4f, 5f, 6f, 7f, 8f, 9f, 10f } };

        var result = FaceHelper.DistanceToFaceLandmark5(points, distance);

        Assert.Equal(101f, result[0, 0, 0]);
        Assert.Equal(202f, result[0, 0, 1]);
        Assert.Equal(103f, result[0, 1, 0]);
        Assert.Equal(204f, result[0, 1, 1]);
        Assert.Equal(105f, result[0, 2, 0]);
        Assert.Equal(206f, result[0, 2, 1]);
        Assert.Equal(107f, result[0, 3, 0]);
        Assert.Equal(208f, result[0, 3, 1]);
        Assert.Equal(109f, result[0, 4, 0]);
        Assert.Equal(210f, result[0, 4, 1]);
    }

