    [Fact]
    public void ScaleFaceLandmark5_MatchesNumpy()
    {
        var landmark5 = new float[,]
        {
            { 10f, 20f }, { 30f, 20f }, { 20f, 30f }, { 15f, 40f }, { 25f, 40f },
        };

        var result = FaceHelper.ScaleFaceLandmark5(landmark5, 1.5);

        float[,] expected =
        {
            { 5f, 15f }, { 35f, 15f }, { 20f, 30f }, { 12.5f, 45f }, { 27.5f, 45f },
        };

        for (var i = 0; i < 5; i++)
        {
            Assert.Equal((double)expected[i, 0], (double)result[i, 0], precision: 4);
            Assert.Equal((double)expected[i, 1], (double)result[i, 1], precision: 4);
        }
    }

    [Fact]
    public void ConvertToFaceLandmark5_MatchesNumpy()
    {
        var landmark68 = new float[68, 2];
        for (var i = 0; i < 68; i++)
        {
            for (var c = 0; c < 2; c++)
            {
                landmark68[i, c] = ((i * 2) + c) * 0.37f + 1.1f;
            }
        }

        var result = FaceHelper.ConvertToFaceLandmark5(landmark68);

        // Python ground truth (numpy.mean over rows 36:42 / 42:48, then landmark68[30], [48], [54]).
        Assert.Equal((double)29.590002f, (double)result[0, 0], precision: 3);
        Assert.Equal((double)29.960001f, (double)result[0, 1], precision: 3);
        Assert.Equal((double)34.029999f, (double)result[1, 0], precision: 3);
        Assert.Equal((double)34.400002f, (double)result[1, 1], precision: 3);
        Assert.Equal(landmark68[30, 0], result[2, 0]);
        Assert.Equal(landmark68[30, 1], result[2, 1]);
        Assert.Equal(landmark68[48, 0], result[3, 0]);
        Assert.Equal(landmark68[48, 1], result[3, 1]);
        Assert.Equal(landmark68[54, 0], result[4, 0]);
        Assert.Equal(landmark68[54, 1], result[4, 1]);
    }

