    [Fact]
    public void CreateBoundingBox_MatchesNumpy()
    {
        // 68x2 seeded with numpy.random.RandomState(1).rand(68,2)*300 in the Python reference.
        var random = new Random(0);
        var landmark68 = new float[68, 2];
        var rows = PythonRandomState1Rows();
        for (var i = 0; i < 68; i++)
        {
            landmark68[i, 0] = rows[i, 0];
            landmark68[i, 1] = rows[i, 1];
        }

        var result = FaceHelper.CreateBoundingBox(landmark68);

        Assert.Equal((double)0.03431244567036629f, (double)result[0], precision: 4);
        Assert.Equal((double)5.594186782836914f, (double)result[1], precision: 4);
        Assert.Equal((double)296.6583251953125f, (double)result[2], precision: 2);
        Assert.Equal((double)299.1968688964844f, (double)result[3], precision: 2);
    }

