    [Fact]
    public void AveragePoints_MatchesNumpy()
    {
        var previous = new float[,] { { 1f, 2f }, { 3f, 4f } };
        var next = new float[,] { { 5f, 6f }, { 7f, 8f } };

        var result = FaceHelper.AveragePoints(previous, next, 0.25);

        Assert.Equal(2f, result[0, 0]);
        Assert.Equal(3f, result[0, 1]);
        Assert.Equal(4f, result[1, 0]);
        Assert.Equal(5f, result[1, 1]);
    }

