    // -----------------------------------------------------------------
    // apply_nms — real cv2.dnn.NMSBoxes ground truth
    // -----------------------------------------------------------------

    [Fact]
    public void ApplyNms_SuppressesOverlappingBox_MatchesPythonCv2()
    {
        var boxes = new[]
        {
            new float[] { 10, 10, 50, 50 },
            new float[] { 12, 12, 52, 52 },
            new float[] { 200, 200, 260, 260 },
        };
        var scores = new[] { 0.9f, 0.8f, 0.95f };

        var kept = FaceHelper.ApplyNms(boxes, scores, 0.5f, 0.4f);

        // Python: cv2.dnn.NMSBoxes(...) -> [2, 0] (highest-score box first, then the next
        // non-suppressed box in score order).
        Assert.Equal(new[] { 2, 0 }, kept);
    }

    [Fact]
    public void ApplyNms_FourBoxes_MatchesPythonCv2()
    {
        var boxes = new[]
        {
            new float[] { 0, 0, 10, 10 },
            new float[] { 1, 1, 11, 11 },
            new float[] { 50, 50, 60, 60 },
            new float[] { 2, 2, 12, 12 },
        };
        var scores = new[] { 0.5f, 0.6f, 0.7f, 0.55f };

        var kept = FaceHelper.ApplyNms(boxes, scores, 0.0f, 0.3f);

        Assert.Equal(new[] { 2, 1 }, kept);
    }

    // -----------------------------------------------------------------
    // estimate_matrix_by_face_landmark_5 / warp_face_by_* — real cv2 ground truth
    // -----------------------------------------------------------------

    private static readonly float[,] SampleLandmark5 =
    {
        { 38.2f, 51.6f }, { 73.4f, 51.1f }, { 56.0f, 68.9f }, { 42.5f, 87.0f }, { 69.6f, 86.5f },
    };

    [Fact]
    public void EstimateMatrixByFaceLandmark5_Arcface112V2_MatchesPythonCv2()
    {
        using var matrix = FaceHelper.EstimateMatrixByFaceLandmark5(SampleLandmark5, WarpTemplate.Arcface112V2, new Size(112, 112));

        Assert.Equal(1.0963318686687598, matrix.At<double>(0, 0), MatrixTolerance);
        Assert.Equal(-0.00563857966825305, matrix.At<double>(0, 1), MatrixTolerance);
        Assert.Equal(-4.9134707279882175, matrix.At<double>(0, 2), MatrixTolerance);
        Assert.Equal(0.00563857966825305, matrix.At<double>(1, 0), MatrixTolerance);
        Assert.Equal(1.0963318686687598, matrix.At<double>(1, 1), MatrixTolerance);
        Assert.Equal(-4.083465980156119, matrix.At<double>(1, 2), MatrixTolerance);
    }

    [Fact]
    public void EstimateMatrixByFaceLandmark5_Ffhq512_MatchesPythonCv2()
    {
        using var matrix = FaceHelper.EstimateMatrixByFaceLandmark5(SampleLandmark5, WarpTemplate.Ffhq512, new Size(512, 512));

        Assert.Equal(3.738762109438293, matrix.At<double>(0, 0), MatrixTolerance);
        Assert.Equal(-0.02228612497608485, matrix.At<double>(0, 1), MatrixTolerance);
        Assert.Equal(48.96554182160578, matrix.At<double>(0, 2), MatrixTolerance);
        Assert.Equal(0.02228612497608485, matrix.At<double>(1, 0), MatrixTolerance);
        Assert.Equal(3.738762109438293, matrix.At<double>(1, 1), MatrixTolerance);
        Assert.Equal(48.048284047427636, matrix.At<double>(1, 2), MatrixTolerance);
    }

    private static Mat CreateGradientFrame()
    {
        var frame = new Mat(200, 200, MatType.CV_8UC3);
        for (var r = 0; r < 200; r++)
        {
            for (var c = 0; c < 200; c++)
            {
                frame.Set(r, c, new Vec3b((byte)(c % 256), (byte)(r % 256), (byte)((r + c) % 256)));
            }
        }

        return frame;
    }

    [Fact]
    public void WarpFaceByFaceLandmark5_MatchesPythonCv2()
    {
        using var frame = CreateGradientFrame();
        var (crop, matrix) = FaceHelper.WarpFaceByFaceLandmark5(frame, SampleLandmark5, WarpTemplate.Arcface112V1, new Size(112, 112));
        using var _crop = crop;
        using var _matrix = matrix;

        Assert.Equal(112, crop.Rows);
        Assert.Equal(112, crop.Cols);

        Assert.Equal(0.9862849109394941, matrix.At<double>(0, 0), MatrixTolerance);
        Assert.Equal(-0.010640218349153914, matrix.At<double>(0, 1), MatrixTolerance);
        Assert.Equal(1.5616098738140922, matrix.At<double>(0, 2), MatrixTolerance);

        // Python ground truth pixel values (int32 BGR) at the four corners and the centre.
        AssertPixel(crop, 0, 0, 0, 0, 0);
        AssertPixel(crop, 0, 111, 111, 0, 111);
        AssertPixel(crop, 111, 0, 0, 112, 112);
        AssertPixel(crop, 111, 111, 112, 111, 223);
        AssertPixel(crop, 56, 56, 56, 56, 112);

        AssertPixelSumClose(2777355, SumPixels(crop));
    }

    [Fact]
    public void WarpFaceByBoundingBox_LargeBox_UsesAreaInterpolation_MatchesPythonCv2()
    {
        using var frame = CreateGradientFrame();
        var boundingBox = new float[] { 20, 30, 150, 160 };
        var (crop, matrix) = FaceHelper.WarpFaceByBoundingBox(frame, boundingBox, new Size(128, 128));
        using var _crop = crop;
        using var _matrix = matrix;

