    private static void AssertPixel(Mat frame, int row, int col, byte b, byte g, byte r, int tolerance = 0)
    {
        var pixel = frame.At<Vec3b>(row, col);
        Assert.True(Math.Abs(pixel.Item0 - b) <= tolerance, $"B channel at ({row},{col}): expected {b}, got {pixel.Item0}.");
        Assert.True(Math.Abs(pixel.Item1 - g) <= tolerance, $"G channel at ({row},{col}): expected {g}, got {pixel.Item1}.");
        Assert.True(Math.Abs(pixel.Item2 - r) <= tolerance, $"R channel at ({row},{col}): expected {r}, got {pixel.Item2}.");
    }

    private static long SumPixels(Mat frame)
    {
        long sum = 0;
        for (var r = 0; r < frame.Rows; r++)
        {
            for (var c = 0; c < frame.Cols; c++)
            {
                var pixel = frame.At<Vec3b>(r, c);
                sum += pixel.Item0 + pixel.Item1 + pixel.Item2;
            }
        }

        return sum;
    }

    /// <summary>
    /// Compares a summed-pixel-value ground truth against the C# result within a small
    /// tolerance rather than exactly. <see cref="SumPixels"/> totals can differ by roughly
    /// 0.01-0.1% between the OpenCvSharp4 4.13 native OpenCV build used here and the
    /// opencv-python-headless 5.0.0 build used to generate the ground truth — the same
    /// algorithm and flags, but two different native builds resolve INTER_AREA/INTER_LINEAR
    /// sub-pixel sampling with tiny rounding differences at some pixels. The corner-pixel
    /// assertions alongside these checks (which land exactly on un-interpolated source pixels)
    /// are exact; this tolerance only covers the aggregate, interpolation-sensitive sum.
    /// </summary>
    private static void AssertPixelSumClose(long expected, long actual)
    {
        var delta = Math.Abs(expected - actual);
        Assert.True(delta <= 2000, $"Pixel sum {actual} too far from Python ground truth {expected} (delta {delta}).");
    }

