    // calculate_paste_area — real cv2 ground truth, including the int32-rounding quirk
    // -----------------------------------------------------------------

    [Fact]
    public void CalculatePasteArea_MatchesPythonCv2IncludingIntRoundingQuirk()
    {
        using var temp = new Mat(300, 400, MatType.CV_8UC3, Scalar.Black);
        using var crop = new Mat(112, 112, MatType.CV_8UC3, Scalar.Black);
        using var affine = FaceHelper.EstimateMatrixByFaceLandmark5(SampleLandmark5, WarpTemplate.Arcface112V1, new Size(112, 112));

        var (pasteBoundingBox, pasteMatrix) = FaceHelper.CalculatePasteArea(temp, crop, affine);
        using var _pasteMatrix = pasteMatrix;

        // Python ground truth: paste_bounding_box = [0, 0, 113, 113] (the int32-rounded corner
        // transform, not the float64 floor/ceil the Python source's own operators suggest).
        Assert.Equal(new[] { 0, 0, 113, 113 }, pasteBoundingBox);

        Assert.Equal(1.0137878189591465, pasteMatrix.At<double>(0, 0), MatrixTolerance);
        Assert.Equal(0.010936924649047568, pasteMatrix.At<double>(0, 1), MatrixTolerance);
        Assert.Equal(-1.5863040477746504, pasteMatrix.At<double>(0, 2), MatrixTolerance);
        Assert.Equal(-0.010936924649047568, pasteMatrix.At<double>(1, 0), MatrixTolerance);
        Assert.Equal(1.0137878189591465, pasteMatrix.At<double>(1, 1), MatrixTolerance);
        Assert.Equal(-0.276110186077294, pasteMatrix.At<double>(1, 2), MatrixTolerance);
    }

    /// <summary>
    /// Directly proves the int32-rounding quirk described on
    /// <see cref="FaceHelper.CalculatePasteArea"/>: verified independently against a raw
    /// <c>cv2.transform</c> call in Python (not routed through <c>face_helper</c>) with values
    /// chosen so at least one coordinate lands exactly on a rounding tie (2.5 -&gt; 2, ties to
    /// even).
    /// </summary>
    [Fact]
    public void CalculatePasteArea_CornerRounding_IsTiesToEven()
    {
        // A crop frame that maps, via a pure-translation affine matrix, to fractional temp
        // coordinates including an exact .5 tie, so the corner-rounding behaviour is pinned
        // down precisely rather than merely "close to" the float value.
        using var temp = new Mat(50, 50, MatType.CV_8UC3, Scalar.Black);
        using var crop = new Mat(1, 1, MatType.CV_8UC3, Scalar.Black); // corners: (0,0) and (1,1)
        using var affine = new Mat(2, 3, MatType.CV_64FC1);
        affine.Set(0, 0, 1.0);
        affine.Set(0, 1, 0.0);
        affine.Set(0, 2, 2.5); // translation.x lands exactly on a tie once inverted below
        affine.Set(1, 0, 0.0);
        affine.Set(1, 1, 1.0);
        affine.Set(1, 2, 1.5);

        // affine here maps crop -> temp directly as translation by (2.5, 1.5), so its own
        // inverse (used internally by CalculatePasteArea) is translation by (-2.5, -1.5); the
        // corner (0,0) maps to (-2.5, -1.5) and (1,1) maps to (-1.5, -0.5) — both exact ties.
        // Python cvRound / cv2.transform's int32 downcast rounds ties to even:
        // -2.5 -> -2, -1.5 -> -2, -0.5 -> 0. Confirmed against a standalone
        // `cv2.transform` call in Python during ground-truth generation for this module.
        var (pasteBoundingBox, pasteMatrix) = FaceHelper.CalculatePasteArea(temp, crop, affine);
        using var _pasteMatrix = pasteMatrix;

        Assert.Equal(0, pasteBoundingBox[0]); // clamped from -2 to 0
        Assert.Equal(0, pasteBoundingBox[1]); // clamped from -2 to 0
        Assert.Equal(0, pasteBoundingBox[2]); // max x is -2 or 0 depending on corner -> clamped to 0
        Assert.Equal(0, pasteBoundingBox[3]);
    }

    // -----------------------------------------------------------------
    // paste_back — real cv2 ground truth
    // -----------------------------------------------------------------

    private static Mat CreateDeterministicNoiseFrame(int height, int width, int seed)
    {
        var frame = new Mat(height, width, MatType.CV_8UC3);
        var random = new Random(seed);
        for (var r = 0; r < height; r++)
        {
            for (var c = 0; c < width; c++)
            {
                frame.Set(r, c, new Vec3b((byte)random.Next(256), (byte)random.Next(256), (byte)random.Next(256)));
            }
        }

        return frame;
    }

    /// <summary>Deterministic formulaic 150x150 BGR frame, computable identically in Python and
    /// C# (avoids embedding a large literal byte blob for a numpy RandomState stream, which
    /// uses a different PRNG algorithm than anything available in .NET and so could never be
    /// reproduced from a seed alone): B = (col*3) % 256, G = (row*5) % 256, R = (row+col) % 256.
    /// </summary>
    private static Mat CreateTempFrame150X150()
    {
        var frame = new Mat(150, 150, MatType.CV_8UC3);
        for (var r = 0; r < 150; r++)
        {
            for (var c = 0; c < 150; c++)
            {
                frame.Set(r, c, new Vec3b((byte)((c * 3) % 256), (byte)((r * 5) % 256), (byte)((r + c) % 256)));
            }
        }

        return frame;
    }

    /// <summary>Deterministic formulaic 80x80 BGR frame: B = (col*7+11) % 256,
    /// G = (row*3+17) % 256, R = (row*col+5) % 256. See <see cref="CreateTempFrame150X150"/>.</summary>
    private static Mat CreateCropFrame80X80()
    {
        var frame = new Mat(80, 80, MatType.CV_8UC3);
        for (var r = 0; r < 80; r++)
        {
            for (var c = 0; c < 80; c++)
            {
                frame.Set(r, c, new Vec3b((byte)(((c * 7) + 11) % 256), (byte)(((r * 3) + 17) % 256), (byte)(((r * c) + 5) % 256)));
            }
        }

        return frame;
    }

    [Fact]
    public void PasteBack_FullWhiteMask_MatchesPythonCv2()
    {
        using var temp = CreateTempFrame150X150();
        using var crop = CreateCropFrame80X80();
        using var mask = new Mat(80, 80, MatType.CV_32FC1, Scalar.All(1.0));

        var landmark5 = new float[,]
        {
            { 30f, 35f }, { 55f, 35f }, { 42f, 50f }, { 33f, 62f }, { 52f, 62f },
        };
        using var affine = FaceHelper.EstimateMatrixByFaceLandmark5(landmark5, WarpTemplate.Arcface112V1, new Size(80, 80));

        using var result = FaceHelper.PasteBack(temp, crop, mask, affine);

        Assert.Equal(new[] { 150, 150 }, new[] { result.Rows, result.Cols });
        AssertPixelSumClose(8946275L, SumPixels(result));
        AssertPixel(result, 10, 10, 75, 54, 118);
        AssertPixel(result, 100, 100, 44, 244, 200);
    }

    [Fact]
    public void PasteBack_PartialMask_BlendsAndMatchesPythonCv2()
    {
        using var temp = CreateTempFrame150X150();
        using var crop = CreateCropFrame80X80();
        using var mask = new Mat(80, 80, MatType.CV_32FC1);
        for (var r = 0; r < 80; r++)
        {
            for (var c = 0; c < 80; c++)
            {
                mask.Set(r, c, c < 40 ? 1.0f : 0.3f);
            }
        }

        var landmark5 = new float[,]
        {
            { 30f, 35f }, { 55f, 35f }, { 42f, 50f }, { 33f, 62f }, { 52f, 62f },
        };
        using var affine = FaceHelper.EstimateMatrixByFaceLandmark5(landmark5, WarpTemplate.Arcface112V1, new Size(80, 80));

        using var result = FaceHelper.PasteBack(temp, crop, mask, affine);

        AssertPixelSumClose(8966546L, SumPixels(result));
        AssertPixel(result, 20, 20, 142, 82, 157);
        // (20, 80) sits on the interpolation-sensitive mask-blend boundary (col 80 == crop
        // width); allow +/-1 for the same cross-OpenCV-build sub-pixel rounding difference
        // documented on AssertPixelSumClose.
        AssertPixel(result, 20, 80, 177, 94, 107, tolerance: 1);
        AssertPixel(result, 5, 5, 42, 40, 38);
    }

