    // -----------------------------------------------------------------
    // merge_matrix — pure double-precision math, verified against numpy.dot chain
    // -----------------------------------------------------------------

    [Fact]
    public void MergeMatrix_ThreeMatrices_MatchesNumpyDotChain()
    {
        using var a = MakeMatrix(1.0, 0.0, 5.0, 0.0, 1.0, 3.0);
        using var b = MakeMatrix(0.9, -0.1, 2.0, 0.1, 0.9, -4.0);
        using var c = MakeMatrix(1.1, 0.05, -1.0, -0.05, 1.1, 0.5);

        using var merged = FaceHelper.MergeMatrix(new[] { a, b, c });

        Assert.Equal(0.9950000000000001, merged.At<double>(0, 0), MatrixTolerance);
        Assert.Equal(-0.06500000000000002, merged.At<double>(0, 1), MatrixTolerance);
        Assert.Equal(5.780000000000001, merged.At<double>(0, 2), MatrixTolerance);
        Assert.Equal(0.06500000000000002, merged.At<double>(1, 0), MatrixTolerance);
        Assert.Equal(0.9950000000000001, merged.At<double>(1, 1), MatrixTolerance);
        Assert.Equal(-0.69, merged.At<double>(1, 2), MatrixTolerance);
    }

    private static Mat MakeMatrix(double m00, double m01, double m02, double m10, double m11, double m12)
    {
        var matrix = new Mat(2, 3, MatType.CV_64FC1);
        matrix.Set(0, 0, m00);
        matrix.Set(0, 1, m01);
        matrix.Set(0, 2, m02);
        matrix.Set(1, 0, m10);
        matrix.Set(1, 1, m11);
        matrix.Set(1, 2, m12);
        return matrix;
    }

