    [Fact]
    public void TransformPoints_IdentityMatrix_ReturnsSamePoints()
    {
        using var identity = MakeMatrix(1, 0, 0, 0, 1, 0);
        var points = new float[,] { { 3f, 4f }, { -2f, 7.5f } };

        var result = FaceHelper.TransformPoints(points, identity);

