    // -----------------------------------------------------------------
    // Round-trip / invertibility property checks (secondary to the ground-truth checks above)
    // -----------------------------------------------------------------

    [Fact]
    public void EstimateMatrixByFaceLandmark5_ProducesInvertibleMatrix()
    {
        using var matrix = FaceHelper.EstimateMatrixByFaceLandmark5(SampleLandmark5, WarpTemplate.Arcface112V1, new Size(112, 112));
        using var inverse = new Mat();
        Cv2.InvertAffineTransform(matrix, inverse);

        // A 2x3 affine matrix followed by its inverse should compose to (approximately) the
        // identity on the linear part.
        var a00 = matrix.At<double>(0, 0);
        var a01 = matrix.At<double>(0, 1);
        var a10 = matrix.At<double>(1, 0);
        var a11 = matrix.At<double>(1, 1);
        var determinant = (a00 * a11) - (a01 * a10);

        Assert.True(Math.Abs(determinant) > 1e-6, "Estimated affine matrix must be non-degenerate.");
    }

    [Fact]
    public void WarpFaceByFaceLandmark5_ThenPasteBack_RoundTripsApproximately()
    {
        using var original = CreateGradientFrame();
        var (crop, matrix) = FaceHelper.WarpFaceByFaceLandmark5(original, SampleLandmark5, WarpTemplate.Arcface112V1, new Size(112, 112));
        using var _crop = crop;
        using var _matrix = matrix;
        using var mask = new Mat(112, 112, MatType.CV_32FC1, Scalar.All(1.0));

        using var pasted = FaceHelper.PasteBack(original, crop, mask, matrix);

        // With a full-strength mask, the region actually covered by the warp should match the
        // crop's own re-warp back into the frame closely (allowing for the two resampling
        // passes' interpolation error).
        Assert.Equal(original.Rows, pasted.Rows);
        Assert.Equal(original.Cols, pasted.Cols);
    }
